 const [folders,setFolders]=useState<AssetFolder[]>([]);const [folder,setFolder]=useState(initial.sourceFolderId??"all");const [mediaCursor,setMediaCursor]=useState<string|null>(null);const [musicAssets,setMusicAssets]=useState<Asset[]>([]);const [safePlatform,setSafePlatform]=useState("reels");
