 const saveChain=useRef<Promise<unknown>>(Promise.resolve());const savedDocument=useRef(JSON.stringify({timeline:initialTimeline(initial),name:initial.name,caption:initial.caption,brandId:initial.brandId,templateId:initial.templateId}));
 const total=timelineDuration(timeline);const schedule=clipSchedule(timeline);const activeClips=schedule.filter(entry=>time>=entry.startMs&&time<entry.endMs);const currentEntry=activeClips.at(-1)??schedule.at(-1);const current=currentEntry?.clip;const selectedLayer=timeline.layers?.find(c=>c.id===selected);const clip=selectedLayer??timeline.clips.find(c=>c.id===selected)??current;const label=timeline.labels.find(l=>l.id===selected)??timeline.labels.find(l=>time>=l.startMs&&time<l.endMs);
