 useEffect(()=>{if(!sourceReady)return;const timer=setTimeout(()=>{void save().catch(e=>{setSaveStatus("Save failed");setError(e.message);});},1200);return()=>clearTimeout(timer);},[timeline,project.name,project.caption,project.brandId,project.templateId,save,sourceReady]);
 useEffect(()=>{const key=`relay-timeline-${initial.id}`;const stored=localStorage.getItem(key);if(stored){try{const draft=JSON.parse(stored);if(draft.revision===(initial.revision??1)&&draft.timeline){setTimeline(draft.timeline);if(draft.meta&&typeof draft.meta.name==="string"&&typeof draft.meta.caption==="string"&&typeof draft.meta.brandId==="string")setProject(p=>({...p,name:draft.meta.name,caption:draft.meta.caption,brandId:draft.meta.brandId,templateId:typeof draft.meta.templateId==="string"?draft.meta.templateId:undefined}));setSaveStatus("Recovered local draft");}}catch{/* Ignore corrupt local recovery. */}}},[initial.id,initial.revision]);
