 const render=async(action:"download"|"compose")=>{setJob(null);setOutputAction(action);setBusy("render");setError("");try{const saved=await save();if(!saved)throw new Error("Save project before rendering.");const p=await api("videos/render","POST",{id:saved.id,async:true});setJob(p.job);}catch(e){setOutputAction(null);setError((e as Error).message);}finally{setBusy("");}};
