 useEffect(()=>{if(!outputAction||!job)return;if(job.status==="failed"||job.status==="cancelled"){setOutputAction(null);return;}if(job.status==="completed"&&job.renderedUrl){setOutputAction(null);if(outputAction==="download")downloadVideo(job);else onCompose({media:{name:`${project.name}.mp4`,url:job.renderedUrl,previewUrl:job.renderedUrl,type:"video",coverUrl:job.coverUrl,thumbOffsetMs:job.coverMs},text:project.caption,brandId:project.brandId});}},[job,outputAction,onCompose,project.name,project.caption,project.brandId]);
 const openMedia=(replace=false,asLayer=false)=>{setMediaDestination(asLayer||Boolean(replace&&selectedLayer)?"layer":"clip");setReplaceSource(replace);setTab("media");setLibraryOpen(true);};
 const selectAudio=(asset:Asset)=>{change({...latest.current,music:{...emptyTimeline().music,url:asset.url,name:asset.name}});setSelected("audio");setLibraryOpen(false);requestAnimationFrame(()=>settings.current?.querySelector(".video-source-settings")?.scrollIntoView({behavior:"smooth",block:"nearest"}));};
 const uploadAudio=async(files:FileList|null)=>{const file=files?.[0];if(!file)return;setBusy("audio-upload");setError("");try{const p=await api("media","POST",{fileName:file.name,contentType:file.type,kind:"music",...(musicFolder!=="all"?{projectId:musicFolder}:{})});const response=await fetch(p.uploadUrl,{method:"PUT",headers:{"Content-Type":file.type},body:file});if(!response.ok)throw new Error("Audio upload failed.");const asset={key:p.key,name:file.name,url:p.url};setMusicAssets(a=>[asset,...a]);selectAudio(asset);}catch(e){setError((e as Error).message);}finally{setBusy("");if(audioUpload.current)audioUpload.current.value="";}};
