 const [w,h]=videoSizes[timeline.aspectRatio];
 const backdrop=timeline.background??{color:activeClips.at(-1)?.clip.deviceFrame?.background??"#000000",endColor:activeClips.at(-1)?.clip.deviceFrame?.backgroundEnd};
 const canvasBackground=backdrop.endColor?`url("data:image/svg+xml;charset=utf-8,${encodeURIComponent(deviceBackgroundSvg(w,h,backdrop.color,backdrop.endColor))}") center / 100% 100% no-repeat`:backdrop.color;
